lass="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Bowler</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Fedora</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Cloche</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Boater</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Beret</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Trilby</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Panama</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Pillbox</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg><span>Bowler</span><svg class="ml-hat" viewBox="0 0 120 70" aria-hidden="true"><ellipse cx="60" cy="56" rx="56" ry="11" class="br"/><path d="M32 54c0-24 6-40 28-40s28 16 28 40" class="cr"/><path d="M32 46c18 5 38 5 56 0v8c-18 5-38 5-56 0z" class="bd"/><path d="M52 16q8 6 16 0" class="pn"/></svg></div></div>

<section class="ml-s ml-sz" id="size"><div class="ml-w ml-sz-g"><div class="ml-head"><svg viewBox="0 0 260 300" aria-hidden="true"><path d="M130 40c-52 0-84 40-84 96 0 44 18 82 44 104 12 10 26 16 40 16s28-6 40-16c26-22 44-60 44-104 0-56-32-96-84-96z" class="hd"/><ellipse cx="130" cy="118" rx="94" ry="20" class="tape"/><g class="tk"><path d="M40 122 v6"/><path d="M52 122 v6"/><path d="M64 122 v6"/><path d="M76 122 v6"/><path d="M88 128 v6"/><path d="M100 128 v6"/><path d="M112 128 v6"/><path d="M124 128 v6"/><path d="M136 128 v6"/><path d="M148 128 v6"/><path d="M160 128 v6"/><path d="M172 128 v6"/><path d="M184 122 v6"/><path d="M196 122 v6"/><path d="M208 122 v6"/><path d="M220 122 v6"/></g><path d="M96 168q10 6 20 0M144 168q10 6 20 0M120 214q10 6 20 0" class="ft"/></svg><p class="ml-head-c"><b id="sz-c">57 cm</b><span>around the widest part</span></p></div>
<div><p class="ml-ey">Tool one</p><h2 class="rv">Hat size finder</h2><p class="ml-p">Wrap a soft tape measure around your head about 1 cm above your ears and eyebrows, where a hat naturally sits. Enter the measurement to see your size in every system.</p>
<div class="ml-unit" id="sz-u" role="group" aria-label="Unit"><button type="button" data-v="cm" class="on">cm</button><button type="button" data-v="in">inches</button></div>
<label class="ml-lb" for="sz-s">Head circumference <output id="sz-o">57 cm</output></label><input type="range" id="sz-s" min="50" max="64" step=".5" value="57">
<dl class="ml-read" aria-live="polite"><div><dt>US fitted</dt><dd id="sz-us">7 1/8</dd></div><div><dt>UK</dt><dd id="sz-uk">7</dd></div><div><dt>EU</dt><dd id="sz-eu">57</dd></div><div><dt>Letter</dt><dd id="sz-l">M</dd></div></dl><p class="ml-small" id="sz-n"></p><figure class="ml-sz-i rv rv-c"><img src="https://images.unsplash.com/photo-1791925719894-8cfae22b4b1a?auto=format&fit=crop&w=600&h=280&q=75" alt="hands holding a wide-brimmed black felt hat" width="600" height="280" loading="lazy"></figure></div></div></section>

<section class="ml-s ml-fc" id="face"><div class="ml-w ml-fc-g"><div><p class="ml-ey">Tool two</p><h2 class="rv">Face shape matcher</h2><p class="ml-p">The right hat balances your features. Choose the face shape closest to yours to see the styles that flatter it most, and the ones to approach with care.</p>
<div class="ml-faces" id="fc-f" role="group" aria-label="Face shape"><button type="button" data-v="0"><svg viewBox="0 0 40 50" aria-hidden="true"><path d="M20 6a16 18 0 1 0 0.1 0z"/></svg><span>Round</span></button><button type="button" data-v="1" class="on"><svg viewBox="0 0 40 50" aria-hidden="true"><path d="M20 3c10 0 14 10 14 22s-6 22-14 22S6 37 6 25 10 3 20 3z"/></svg><span>Oval</span></button><button type="button" data-v="2"><svg viewBox="0 0 40 50" aria-hidden="true"><path d="M6 6h28v34c0 4-4 7-14 7S6 44 6 40z"/></svg><span>Square</span></button><button type="button" data-v="3"><svg viewBox="0 0 40 50" aria-hidden="true"><path d="M4 8c4-4 12-4 16 2 4-6 12-6 16-2 0 14-8 30-16 38C12 38 4 22 4 8z"/></svg><span>Heart</span></button><button type="button" data-v="4"><svg viewBox="0 0 40 50" aria-hidden="true"><path d="M20 2c8 0 11 8 11 23s-3 23-11 23S9 40 9 25 12 2 20 2z"/></svg><span>Long</span></button></div><figure class="ml-fc-i rv rv-c"><img src="https://images.unsplash.com/photo-1734092916497-2105a961a00a?auto=format&fit=crop&w=600&h=300&q=75" alt="a woman arranging a hat on a stand" width="600" height="300" loading="lazy"></figure></div>
<div class="ml-card" aria-live="polite"><p class="ml-scr">your best match</p><h3 id="fc-t">Fedora</h3><p id="fc-d" class="ml-p"></p><div class="ml-sil" id="fc-s"></div><dl><div><dt>Also lovely</dt><dd id="fc-a"></dd></div><div><dt>Go gently with</dt><dd id="fc-x"></dd></div></dl></div></div></section>

<section class="ml-s ml-an"><div class="ml-w ml-an-g"><figure class="ml-an-i pxw"><img data-px=".1" src="https://images.unsplash.com/photo-1752014364743-e80acc2c9b6e?auto=format&fit=crop&w=520&h=640&q=75" alt="a hat resting on a wooden hat block" width="520" height="640" loading="lazy"></figure><div><p class="ml-ey">Anatomy of a hat</p><h2 class="rv">Know the parts, choose with confidence</h2><div class="ml-an-v"><svg viewBox="0 0 120 76" aria-hidden="true"><ellipse cx="60" cy="62" rx="58" ry="12" class="br"/><path d="M28 60c0-30 8-50 32-50s32 20 32 50" class="cr"/><path d="M28 50c20 6 44 6 64 0v10c-20 6-44 6-64 0z" class="bd"/><path d="M50 12q10 8 20 0" class="pn"/></svg><button type="button" class="ml-pin" data-i="0" style="left:50.0%;top:36.8%" aria-label="Crown">1</button><button type="button" class="ml-pin" data-i="1" style="left:50.0%;top:15.8%" aria-label="Pinch">2</button><button type="button" class="ml-pin" data-i="2" style="left:68.3%;top:65.8%" aria-label="Band">3</button><button type="button" class="ml-pin" data-i="3" style="left:86.7%;top:81.6%" aria-label="Brim">4</button><button type="button" class="ml-pin" data-i="4" style="left:30.0%;top:68.4%" aria-label="Sweatband">5</button></div><ul class="ml-parts" id="pt"><li data-i="0" class="on"><b>Crown</b><p>The top of the hat that sits over your head. Its height balances your face.</p></li><li data-i="1"><b>Pinch</b><p>The dents at the front of a fedora, made to grip the hat.</p></li><li data-i="2"><b>Band</b><p>A ribbon or leather strip where the crown meets the brim.</p></li><li data-i="3"><b>Brim</b><p>The edge that shades your face. Width changes the whole look.</p></li><li data-i="4"><b>Sweatband</b><p>The inner band that touches your forehead and sets the fit.</p></li></ul></div></div></section>

<section class="ml-s ml-st"><div class="ml-w ml-st-h"><p class="ml-ey">Five classics</p><h2 class="rv">A hat for every head</h2><p class="ml-p">Drag to browse</p></div><div class="hs ml-hs"><figure class="ml-sty"><div class="ml-sty-i"><img src="https://images.unsplash.com/photo-1791356633161-8b2120231b53?auto=format&fit=crop&w=400&h=500&q=75" alt="a row of fedoras on a glass counter in a vintage hat shop" width="400" height="500" loading="lazy"></div><figcaption><b>Fedora</b><span>Pinched crown, medium brim</span></figcaption></figure><figure class="ml-sty"><div class="ml-sty-i"><img src="https://images.unsplash.com/photo-1778865575946-4d26642a0323?auto=format&fit=crop&w=400&h=500&q=75" alt="a red beret on a mannequin head" width="400" height="500" loading="lazy"></div><figcaption><b>Beret</b><span>Soft, round and flat</span></figcaption></figure><figure class="ml-sty"><div class="ml-sty-i"><img src="https://images.unsplash.com/photo-1779447810263-9ac2da5cf6f9?auto=format&fit=crop&w=400&h=500&q=75" alt="a woven straw hat on a dark background" width="400" height="500" loading="lazy"></div><figcaption><b>Boater</b><span>Flat crown, stiff straw</span></figcaption></figure><figure class="ml-sty"><div class="ml-sty-i"><img src="https://images.unsplash.com/photo-1785088560849-55fab169cdc4?auto=format&fit=crop&w=400&h=500&q=75" alt="a green felt hat with feathers on a stand" width="400" height="500" loading="lazy"></div><figcaption><b>Trilby</b><span>Short, snappy brim</span></figcaption></figure><figure class="ml-sty"><div class="ml-sty-i"><img src="https://images.unsplash.com/photo-1548652035-16d4cacff1e6?auto=format&fit=crop&w=400&h=500&q=75" alt="a woman in a beige sun hat in a wheat field" width="400" height="500" loading="lazy"></div><figcaption><b>Sun hat</b><span>Wide, floppy and shady</span></figcaption></figure></div></section>

